use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

pub fn power_for(value: Drone_Lifecycle_Governor::Lifecycle_Phase) -> Drone_Lifecycle_Governor::Power_Permission
{
  if (value == Drone_Lifecycle_Governor::Lifecycle_Phase::Off) {
    Drone_Lifecycle_Governor::Power_Permission::Disabled
  } else {
    if (value == Drone_Lifecycle_Governor::Lifecycle_Phase::Standby) {
      Drone_Lifecycle_Governor::Power_Permission::Standby_Enabled
    } else {
      Drone_Lifecycle_Governor::Power_Permission::Operational_Enabled
    }
  }
}

pub fn charging_for(value: Drone_Lifecycle_Governor::Lifecycle_Phase) -> bool
{
  value == Drone_Lifecycle_Governor::Lifecycle_Phase::Charging
}

pub fn flight_for(value: Drone_Lifecycle_Governor::Lifecycle_Phase) -> bool
{
  value == Drone_Lifecycle_Governor::Lifecycle_Phase::Flying
}

/** Initialize EntryPointContract
  *
  * guarantee INITIAL_ENABLEMENT_DISABLED
  *   Enablement starts with all logical permissions disabled
  * @param api_lifecycle_enablement outgoing data port
  */
pub fn initialize_INITIAL_ENABLEMENT_DISABLED(api_lifecycle_enablement: Drone_Lifecycle_Governor::Lifecycle_Enablement) -> bool
{
  (api_lifecycle_enablement.power == Drone_Lifecycle_Governor::Power_Permission::Disabled) &
    (api_lifecycle_enablement.charging_permitted == false) &
    (api_lifecycle_enablement.flight_permitted == false)
}

/** IEP-Guar: Initialize Entrypoint for enablement_derivation
  *
  * @param api_lifecycle_enablement outgoing data port
  */
pub fn initialize_IEP_Guar(api_lifecycle_enablement: Drone_Lifecycle_Governor::Lifecycle_Enablement) -> bool
{
  initialize_INITIAL_ENABLEMENT_DISABLED(api_lifecycle_enablement)
}

/** IEP-Post: Initialize Entrypoint Post-Condition
  *
  * @param api_lifecycle_enablement outgoing data port
  */
pub fn initialize_IEP_Post(api_lifecycle_enablement: Drone_Lifecycle_Governor::Lifecycle_Enablement) -> bool
{
  initialize_IEP_Guar(api_lifecycle_enablement)
}

/** Compute Entrypoint Contract
  *
  * guarantee ENABLEMENT_TOTAL
  *   The selected phase determines three independently meaningful permission fields
  * @param api_selected_phase incoming data port
  * @param api_lifecycle_enablement outgoing data port
  */
pub fn compute_spec_ENABLEMENT_TOTAL_guarantee(
  api_selected_phase: Drone_Lifecycle_Governor::Lifecycle_Phase,
  api_lifecycle_enablement: Drone_Lifecycle_Governor::Lifecycle_Enablement) -> bool
{
  (api_lifecycle_enablement.power == power_for(api_selected_phase)) &
    (api_lifecycle_enablement.charging_permitted == charging_for(api_selected_phase)) &
    (api_lifecycle_enablement.flight_permitted == flight_for(api_selected_phase))
}

/** CEP-T-Guar: Top-level guarantee contracts for enablement_derivation's compute entrypoint
  *
  * @param api_selected_phase incoming data port
  * @param api_lifecycle_enablement outgoing data port
  */
pub fn compute_CEP_T_Guar(
  api_selected_phase: Drone_Lifecycle_Governor::Lifecycle_Phase,
  api_lifecycle_enablement: Drone_Lifecycle_Governor::Lifecycle_Enablement) -> bool
{
  let r0: bool = compute_spec_ENABLEMENT_TOTAL_guarantee(api_selected_phase, api_lifecycle_enablement);

  return r0;
}

/** CEP-Post: Compute Entrypoint Post-Condition for enablement_derivation
  *
  * @param api_selected_phase incoming data port
  * @param api_lifecycle_enablement outgoing data port
  */
pub fn compute_CEP_Post(
  api_selected_phase: Drone_Lifecycle_Governor::Lifecycle_Phase,
  api_lifecycle_enablement: Drone_Lifecycle_Governor::Lifecycle_Enablement) -> bool
{
  // CEP-Guar: guarantee clauses of enablement_derivation's compute entrypoint
  let r0: bool = compute_CEP_T_Guar(api_selected_phase, api_lifecycle_enablement);

  return r0;
}
